public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v, Node l, Node r) { val = v; left = l; right = r; }
    }
    // Depth is passed DOWN: every child gets depth + 1.
    static void printDepths(Node n, int depth) {
        if (n == null) return;
        System.out.println("node " + n.val + " depth " + depth);
        printDepths(n.left, depth + 1);
        printDepths(n.right, depth + 1);
    }
    // Height is returned UP: 1 + the taller child. Empty tree = 0 (counting nodes).
    static int height(Node n) {
        if (n == null) return 0;
        return 1 + Math.max(height(n.left), height(n.right));
    }
    public static void main(String[] args) {
        Node root = new Node(1, new Node(2, new Node(4, null, null), new Node(5, null, null)), new Node(3, null, null));
        System.out.println("Tree: 1 -> (2 -> (4, 5), 3)");
        printDepths(root, 0);
        int h = height(root);
        System.out.println("height counting nodes = " + h);
        // Counting edges is always one less than counting nodes.
        System.out.println("height counting edges = " + (h - 1));
        // Time O(N), space O(h) for the recursion stack.
    }
}

