        int val; Node left, right;
        Node(int v, Node l, Node r) { val = v; left = l; right = r; }
    }
    // mode 0 = preorder, 1 = inorder, 2 = postorder.
    // The walk is the same; only the moment we record the node changes.
    static void walk(Node n, int mode, StringBuilder out) {
        if (n == null) return;
        if (mode == 0) out.append(n.val).append(' ');   // before both children
        walk(n.left, mode, out);
        if (mode == 1) out.append(n.val).append(' ');   // between the children
        walk(n.right, mode, out);
        if (mode == 2) out.append(n.val).append(' ');   // after both children
    }
    public static void main(String[] args) {
        Node root = new Node(1, new Node(2, new Node(4, null, null), new Node(5, null, null)), new Node(3, null, null));
        System.out.println("Tree: 1 -> (2 -> (4, 5), 3)");
        String[] names = {"preorder ", "inorder  ", "postorder"};
        for (int mode = 0; mode < 3; mode++) {
            StringBuilder out = new StringBuilder();
            walk(root, mode, out);
            System.out.println(names[mode] + ": " + out.toString().trim());
        }
        // Each walk: time O(N), space O(h) for the recursion stack.
    }
