import java.util.*;

public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v, Node l, Node r) { val = v; left = l; right = r; }
    }
    public static void main(String[] args) {
        Node root = new Node(4,
            new Node(2, new Node(1, null, null), new Node(3, null, null)),
            new Node(6, new Node(5, null, null), new Node(7, null, null)));
        System.out.println("BST: 4 -> (2 -> (1, 3), 6 -> (5, 7))");
        Deque<Node> stack = new ArrayDeque<>();
        StringBuilder out = new StringBuilder();
        Node cur = root;
        int maxStack = 0;
        while (cur != null || !stack.isEmpty()) {
            // Slide left, remembering every node we still owe a visit.
            while (cur != null) { stack.push(cur); cur = cur.left; }
            maxStack = Math.max(maxStack, stack.size());
            // The top of the stack has its whole left side done: record it.
            Node n = stack.pop();
            out.append(n.val).append(' ');
            // Then handle its right subtree the same way.
            cur = n.right;
        }
        System.out.println("inorder: " + out.toString().trim());
        System.out.println("largest stack size: " + maxStack);
        // Time O(N): each node is pushed and popped once. Space O(h).
    }
}

