import java.util.*;

public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v, Node l, Node r) { val = v; left = l; right = r; }
    }
    static int maxDepth(Node n) {   // DFS: a whole-subtree question
        return n == null ? 0 : 1 + Math.max(maxDepth(n.left), maxDepth(n.right));
    }
    public static void main(String[] args) {
        Node root = new Node(1,
            new Node(2, new Node(4, new Node(7, null, null), null), new Node(5, null, null)),
            new Node(3, null, null));
        System.out.println("Tree: 1 -> (2 -> (4 -> (7), 5), 3)");
        Deque<Node> queue = new ArrayDeque<>();
        queue.add(root);
        int level = 0, leafVal = -1, leafDepth = -1;
        while (!queue.isEmpty()) {
            int size = queue.size();   // how many nodes are on this level
            StringBuilder line = new StringBuilder();
            for (int i = 0; i < size; i++) {
                Node n = queue.poll();
                line.append(n.val).append(' ');
                // The first leaf BFS meets is the nearest one.
                if (leafDepth < 0 && n.left == null && n.right == null) { leafVal = n.val; leafDepth = level + 1; }
                if (n.left != null) queue.add(n.left);
                if (n.right != null) queue.add(n.right);
            }
            System.out.println("level " + level + ": " + line.toString().trim());
            level++;
        }
        System.out.println("BFS: nearest leaf is " + leafVal + " at depth " + leafDepth + " (counting nodes)");
        System.out.println("DFS: maximum depth = " + maxDepth(root));
        // Both are O(N) time. BFS space O(widest level), DFS space O(h).
    }
}

