class Node {
    public int val; public Node left, right;
    public Node(int v, Node l = null, Node r = null) { val = v; left = l; right = r; }
}
class Program {
    static int MaxDepth(Node n) {   // DFS: a whole-subtree question
        return n == null ? 0 : 1 + Math.Max(MaxDepth(n.left), MaxDepth(n.right));
    }
    static void Main() {
        Node root = new Node(1, new Node(2, new Node(4, new Node(7)), new Node(5)), new Node(3));
        Console.WriteLine("Tree: 1 -> (2 -> (4 -> (7), 5), 3)");
        Queue<Node> queue = new Queue<Node>();
        queue.Enqueue(root);
        int level = 0, leafVal = -1, leafDepth = -1;
        while (queue.Count > 0) {
            int size = queue.Count;   // how many nodes are on this level
            List<int> line = new List<int>();
            for (int i = 0; i < size; i++) {
                Node n = queue.Dequeue();
                line.Add(n.val);
                // The first leaf BFS meets is the nearest one.
                if (leafDepth < 0 && n.left == null && n.right == null) { leafVal = n.val; leafDepth = level + 1; }
                if (n.left != null) queue.Enqueue(n.left);
                if (n.right != null) queue.Enqueue(n.right);
