public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v, Node l, Node r) { val = v; left = l; right = r; }
    }
    static int best = 0;
    // Returns the height in nodes (what the parent needs) and
    // records the longest path that bends at this node (what we want).
    static int height(Node n) {
        if (n == null) return 0;
        int lh = height(n.left), rh = height(n.right);
        best = Math.max(best, lh + rh);   // edges on the path through n
        return 1 + Math.max(lh, rh);      // a parent can use one side only
    }
    public static void main(String[] args) {
        Node left = new Node(2,
            new Node(4, new Node(6, new Node(8, null, null), null), null),
            new Node(5, new Node(7, new Node(9, null, null), null), null));
        Node root = new Node(1, left, new Node(3, null, null));
        System.out.println("Tree: 1 -> (2 -> (4 -> (6 -> (8)), 5 -> (7 -> (9))), 3)");
        height(root);
        System.out.println("diameter = " + best + " edges (path 8-6-4-2-5-7-9, bending at node 2)");
        int viaRoot = height(root.left) + height(root.right);
        System.out.println("longest path through the root = " + viaRoot + " edges");
        // Time O(N): one visit per node. Space O(h) for the recursion stack.
    }
}

