public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v, Node l, Node r) { val = v; left = l; right = r; }
    }
    // Any binary tree: each call reports p, q, or their LCA if found below.
    static Node lcaTree(Node n, int p, int q) {
        if (n == null || n.val == p || n.val == q) return n;
        Node l = lcaTree(n.left, p, q), r = lcaTree(n.right, p, q);
        if (l != null && r != null) return n;   // one target on each side
        return l != null ? l : r;               // pass up whatever was found
    }
    // BST: walk down until p and q stop being on the same side.
    static Node lcaBst(Node n, int p, int q) {
        while (n != null) {
            if (p < n.val && q < n.val) n = n.left;
            else if (p > n.val && q > n.val) n = n.right;
            else return n;                      // the split point
        }
        return null;
    }
    public static void main(String[] args) {
        Node root = new Node(6,
            new Node(2, new Node(0, null, null), new Node(4, new Node(3, null, null), new Node(5, null, null))),
            new Node(8, new Node(7, null, null), new Node(9, null, null)));
        System.out.println("BST: 6 -> (2 -> (0, 4 -> (3, 5)), 8 -> (7, 9))");
        int[][] pairs = {{2, 8}, {2, 4}, {3, 5}};
        for (int[] pr : pairs) {
            System.out.println("LCA(" + pr[0] + ", " + pr[1] + "): binary-tree method = " + lcaTree(root, pr[0], pr[1]).val
                + ", BST method = " + lcaBst(root, pr[0], pr[1]).val);
        }
        // Binary tree: O(N) time, O(h) space. BST: O(h) time, O(1) space.
    }
