public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v) { val = v; }
    }
    static Node insert(Node n, int key) {
        if (n == null) return new Node(key);
        if (key < n.val) n.left = insert(n.left, key); else n.right = insert(n.right, key);
        return n;
    }
    static Node delete(Node n, int key) {
        if (n == null) return null;
        if (key < n.val) n.left = delete(n.left, key);         // re-link the returned subtree
        else if (key > n.val) n.right = delete(n.right, key);
        else {
            if (n.left == null) return n.right;                // leaf or only a right child
            if (n.right == null) return n.left;                // only a left child
            Node s = n.right;                                  // two children: find the successor
            while (s.left != null) s = s.left;
            n.val = s.val;                                     // copy it up, then remove it below
            n.right = delete(n.right, s.val);
        }
        return n;
    }
    static void inorder(Node n, StringBuilder out) {
        if (n == null) return;
        inorder(n.left, out); out.append(n.val).append(' '); inorder(n.right, out);
    }
    static String show(Node root) {
        StringBuilder out = new StringBuilder(); inorder(root, out); return out.toString().trim();
    }
    public static void main(String[] args) {
        Node root = null;
        for (int k : new int[]{50, 30, 70, 20, 40, 60, 80}) root = insert(root, k);
        System.out.println("Insert: 50 30 70 20 40 60 80");
        System.out.println("inorder: " + show(root));
        root = delete(root, 20); System.out.println("delete 20 (leaf): " + show(root));
        root = delete(root, 30); System.out.println("delete 30 (one child): " + show(root));
        root = delete(root, 50); System.out.println("delete 50 (two children): " + show(root));
        System.out.println("root is now " + root.val);
        // Insert and delete are O(h) time, O(h) recursion space.
    }
}

