using System;
using System.Collections.Generic;
class Node {
    public int val; public Node left, right;
    public Node(int v) { val = v; }
}
class Program {
    static Node Insert(Node n, int key) {
        if (n == null) return new Node(key);
        if (key < n.val) n.left = Insert(n.left, key); else n.right = Insert(n.right, key);
        return n;
    }
    static Node Delete(Node n, int key) {
        if (n == null) return null;
        if (key < n.val) n.left = Delete(n.left, key);         // re-link the returned subtree
        else if (key > n.val) n.right = Delete(n.right, key);
        else {
            if (n.left == null) return n.right;                // leaf or only a right child
            if (n.right == null) return n.left;                // only a left child
            Node s = n.right;                                  // two children: find the successor
            while (s.left != null) s = s.left;
            n.val = s.val;                                     // copy it up, then remove it below
            n.right = Delete(n.right, s.val);
        }
        return n;
    }
    static void Inorder(Node n, List<int> o) {
        if (n == null) return;
        Inorder(n.left, o); o.Add(n.val); Inorder(n.right, o);
    }
    static string Show(Node root) {
        List<int> o = new List<int>(); Inorder(root, o); return string.Join(" ", o);
    }
    static void Main() {
        Node root = null;
        foreach (int k in new int[] { 50, 30, 70, 20, 40, 60, 80 }) root = Insert(root, k);
        Console.WriteLine("Insert: 50 30 70 20 40 60 80");
        Console.WriteLine("inorder: " + Show(root));
        root = Delete(root, 20); Console.WriteLine("delete 20 (leaf): " + Show(root));
        root = Delete(root, 30); Console.WriteLine("delete 30 (one child): " + Show(root));
        root = Delete(root, 50); Console.WriteLine("delete 50 (two children): " + Show(root));
        Console.WriteLine("root is now " + root.val);
        // Insert and delete are O(h) time, O(h) recursion space.
    }
}

