import java.util.*;

public class Main {
    static class Node {
        int val, size = 1; Node left, right;   // size = nodes in this subtree
        Node(int v) { val = v; }
    }
    static Node insert(Node n, int key) {
        if (n == null) return new Node(key);
        if (key < n.val) n.left = insert(n.left, key); else n.right = insert(n.right, key);
        n.size++;                               // one more node below n
        return n;
    }
    // Way 1: iterative inorder, stop at the k-th pop. O(h + k) time.
    static int kthInorder(Node root, int k) {
        Deque<Node> stack = new ArrayDeque<>();
        Node cur = root;
        while (true) {
            while (cur != null) { stack.push(cur); cur = cur.left; }
            Node n = stack.pop();
            if (--k == 0) return n.val;
            cur = n.right;
        }
    }
    // Way 2: use subtree sizes to skip whole subtrees. O(h) time.
    static int kthBySize(Node n, int k) {
        while (true) {
            int leftSize = n.left == null ? 0 : n.left.size;
            if (k == leftSize + 1) return n.val;
            if (k <= leftSize) n = n.left;
            else { k -= leftSize + 1; n = n.right; }   // skip the left side and n itself
        }
    }
    public static void main(String[] args) {
        Node root = null;
        for (int key : new int[]{5, 3, 8, 1, 4, 7, 9}) root = insert(root, key);
        System.out.println("Insert: 5 3 8 1 4 7 9");
        System.out.println("k = 3, inorder walk -> " + kthInorder(root, 3));
        System.out.println("k = 3, subtree sizes -> " + kthBySize(root, 3));
        System.out.println("k = 6, subtree sizes -> " + kthBySize(root, 6));
        // Space: O(h) for the stack in way 1, O(1) in way 2.
    }
}

