import java.util.*;

public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v) { val = v; }
    }
    static int[] pre = {3, 9, 20, 15, 7}, in = {9, 3, 15, 20, 7};
    static Map<Integer, Integer> pos = new HashMap<>();   // value -> index in inorder
    static int next = 0;                                  // next unused preorder index

    // Builds the subtree whose values are in[lo..hi].
    static Node build(int lo, int hi) {
        if (lo > hi) return null;
        Node root = new Node(pre[next++]);    // the next preorder value is this subtree's root
        int m = pos.get(root.val);            // O(1) lookup of where it splits inorder
        root.left = build(lo, m - 1);         // left first: preorder lists the left subtree next
        root.right = build(m + 1, hi);
        return root;
    }
    static void postorder(Node n, StringBuilder out) {
        if (n == null) return;
        postorder(n.left, out); postorder(n.right, out); out.append(n.val).append(' ');
    }
    public static void main(String[] args) {
        for (int i = 0; i < in.length; i++) pos.put(in[i], i);
        Node root = build(0, in.length - 1);
        StringBuilder out = new StringBuilder();
        postorder(root, out);
        System.out.println("preorder: 3 9 20 15 7");
        System.out.println("inorder: 9 3 15 20 7");
        System.out.println("root = " + root.val + ", left child = " + root.left.val + ", right child = " + root.right.val);
        System.out.println("postorder of built tree: " + out.toString().trim());
        // Time O(N): one node and one map lookup per value. Space O(N) for the map.
    }
}

