public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v) { val = v; }
    }
    static Node root;
    static int height;   // deepest level reached so far, counting nodes

    // Plain BST insert with a loop (no balancing). Cost = depth of the new node.
    static void insert(int key) {
        int depth = 1;
        if (root == null) { root = new Node(key); height = Math.max(height, depth); return; }
        Node n = root;
        while (true) {
            depth++;
            if (key < n.val) { if (n.left == null) { n.left = new Node(key); break; } n = n.left; }
            else { if (n.right == null) { n.right = new Node(key); break; } n = n.right; }
        }
        height = Math.max(height, depth);
    }
    // Insert the middle key first, then the middles of each half: a balanced shape.
    static void insertMiddleFirst(int lo, int hi) {
        if (lo > hi) return;
        int mid = (lo + hi) / 2;
        insert(mid);
        insertMiddleFirst(lo, mid - 1);
        insertMiddleFirst(mid + 1, hi);
    }
    public static void main(String[] args) {
        int n = 1000;
        for (int k = 1; k <= n; k++) insert(k);          // sorted keys: every key goes right
        System.out.println("Insert 1.." + n + " in sorted order: height = " + height);
        root = null; height = 0;
        insertMiddleFirst(1, n);
        System.out.println("Insert the same keys middle-first: height = " + height);
        System.out.println("A red-black tree keeps the height near log2(N) for any insert order");
        // Search costs O(height): O(N) for the chain, O(log N) when balanced.
    }
}

