import java.util.*;

public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v, Node l, Node r) { val = v; left = l; right = r; }
    }
    // Preorder, writing "#" for every empty child so the shape is recorded.
    static void encode(Node n, List<String> out) {
        if (n == null) { out.add("#"); return; }
        out.add(String.valueOf(n.val));
        encode(n.left, out);
        encode(n.right, out);
    }
    static String serialize(Node root) {
        List<String> out = new ArrayList<>();
        encode(root, out);
        return String.join(",", out);
    }
    static int pos;
    // Mirrors encode: read one token, then a whole left subtree, then a right one.
    static Node decode(String[] tokens) {
        String t = tokens[pos++];
        if (t.equals("#")) return null;
        Node n = new Node(Integer.parseInt(t), null, null);
        n.left = decode(tokens);
        n.right = decode(tokens);
        return n;
    }
    public static void main(String[] args) {
        Node root = new Node(1, new Node(2, null, null),
            new Node(2, new Node(4, null, null), new Node(2, null, null)));
        System.out.println("Tree with duplicates: 1 -> (2, 2 -> (4, 2))");
        String s = serialize(root);
        System.out.println("serialized: " + s);
        pos = 0;
        Node copy = decode(s.split(","));
        String again = serialize(copy);
        System.out.println("decoded and serialized again: " + again);
        System.out.println("round trip matches: " + (s.equals(again) ? "yes" : "no"));
        // Both directions: O(N) time, O(N) space for the tokens, O(h) recursion.
    }
}

