        o.Add(n.val.ToString());
        Encode(n.left, o);
        Encode(n.right, o);
    }
    static string Serialize(Node root) {
        List<string> o = new List<string>();
        Encode(root, o);
        return string.Join(",", o);
    }
    static int pos;
    // Mirrors Encode: read one token, then a whole left subtree, then a right one.
    static Node Decode(string[] tokens) {
        string t = tokens[pos++];
        if (t == "#") return null;
        Node n = new Node(int.Parse(t));
        n.left = Decode(tokens);
        n.right = Decode(tokens);
        return n;
    }
