        Console.WriteLine("Tree with duplicates: 1 -> (2, 2 -> (4, 2))");
        string s = Serialize(root);
        Console.WriteLine("serialized: " + s);
        pos = 0;
        Node copy = Decode(s.Split(','));
        string again = Serialize(copy);
        Console.WriteLine("decoded and serialized again: " + again);
        Console.WriteLine("round trip matches: " + (s == again ? "yes" : "no"));
        // Both directions: O(N) time, O(N) space for the tokens, O(h) recursion.
