import java.util.*;

public class Main {
    static class Node {
        int val; Node left, right;
        Node(int v, Node l) { val = v; left = l; }
    }
    public static void main(String[] args) {
        int n = 100000;
        // Build a chain: every node has only a left child (what sorted inserts produce).
        Node root = null;
        for (int i = 0; i < n; i++) root = new Node(i, root);
        System.out.println("Skewed tree with " + n + " nodes (each node has only a left child)");

        // Our own stack lives on the heap, so depth is limited by memory, not by the call stack.
        Deque<Node> nodes = new ArrayDeque<>();
        Deque<Integer> depths = new ArrayDeque<>();
        nodes.push(root); depths.push(1);
        int height = 0;
        while (!nodes.isEmpty()) {
            Node cur = nodes.pop();
            int d = depths.pop();
            height = Math.max(height, d);   // deepest node seen so far
            if (cur.left != null) { nodes.push(cur.left); depths.push(d + 1); }
            if (cur.right != null) { nodes.push(cur.right); depths.push(d + 1); }
        }
        System.out.println("height with an explicit stack = " + height);
        System.out.println("A recursive height() would need " + n + " nested calls and can overflow the call stack");
        // Time O(N), space O(h) on the heap.
    }
}

